import{c as a,Q as s,j as t,m as n}from"./chunks/framework.DxgWTcNC.js";const g=JSON.parse('{"title":"File Format Reference","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/C-file-formats.md","filePath":"appendix/C-file-formats.md","lastUpdated":null}'),o={name:"appendix/C-file-formats.md"};function i(d,e,c,p,r,l){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="file-format-reference" tabindex="-1">File Format Reference <a class="header-anchor" href="#file-format-reference" aria-label="Permalink to &quot;File Format Reference&quot;">​</a></h1><p>Concise reference for the file formats you encounter in embedded firmware reverse engineering. For each: the magic bytes, the layout, how to recognise it, and how to extract or convert.</p><h2 id="elf-executable-and-linkable-format" tabindex="-1">ELF (Executable and Linkable Format) <a class="header-anchor" href="#elf-executable-and-linkable-format" aria-label="Permalink to &quot;ELF (Executable and Linkable Format)&quot;">​</a></h2><p><strong>Magic:</strong> <code>7F 45 4C 46</code> (&quot;<code>\\x7FELF</code>&quot;) at offset 0.</p><p><strong>Layout:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>ELF Header (52 bytes for ELF32, 64 for ELF64)</span></span>
<span class="line"><span>  e_ident[16]    magic, class, endianness, version, OS ABI</span></span>
<span class="line"><span>  e_type         executable/dynamic/object/core</span></span>
<span class="line"><span>  e_machine      EM_ARM, EM_MIPS, EM_RISCV, EM_XTENSA, ...</span></span>
<span class="line"><span>  e_version      always 1</span></span>
<span class="line"><span>  e_entry        entry point virtual address</span></span>
<span class="line"><span>  e_phoff        program header table offset</span></span>
<span class="line"><span>  e_shoff        section header table offset</span></span>
<span class="line"><span>  e_flags        machine-specific flags</span></span>
<span class="line"><span>  e_ehsize       size of this header</span></span>
<span class="line"><span>  e_phentsize    program header entry size</span></span>
<span class="line"><span>  e_phnum        number of program headers</span></span>
<span class="line"><span>  e_shentsize    section header entry size</span></span>
<span class="line"><span>  e_shnum        number of section headers</span></span>
<span class="line"><span>  e_shstrndx     index of string table</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Program Headers (defines what gets loaded)</span></span>
<span class="line"><span>Section Headers (defines code/data/symbols/relocations)</span></span>
<span class="line"><span>... payloads ...</span></span></code></pre></div><p><strong>Recognise:</strong> <code>file binary.elf</code> shows <code>ELF 32-bit LSB executable, ARM</code> or similar. R2 reads it directly.</p><p><strong>Extract sections:</strong> <code>objcopy -O binary --only-section=.text</code> extracts <code>.text</code> to a flat binary. <code>readelf -S</code> lists sections.</p><p><strong>Useful sections:</strong> <code>.text</code> (code), <code>.rodata</code> (constants), <code>.data</code> (initialised globals), <code>.bss</code> (zeroed globals, not in file), <code>.symtab</code>/<code>.strtab</code> (symbols), <code>.dynamic</code> (dynamic linking), <code>.note.gnu.build-id</code>.</p><h2 id="intel-hex-hex" tabindex="-1">Intel HEX (.hex) <a class="header-anchor" href="#intel-hex-hex" aria-label="Permalink to &quot;Intel HEX (.hex)&quot;">​</a></h2><p><strong>ASCII format</strong>, line-based. Each line starts with <code>:</code>.</p><p><strong>Line format:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>:LL AAAA TT DD..DD CC</span></span></code></pre></div><ul><li><code>:</code> — start</li><li><code>LL</code> — byte count (2 hex digits)</li><li><code>AAAA</code> — 16-bit address (high bits set by extended-address records)</li><li><code>TT</code> — record type: <ul><li><code>00</code> data</li><li><code>01</code> end-of-file</li><li><code>02</code> extended segment address (older)</li><li><code>04</code> extended linear address (sets bits 16–31 of address)</li><li><code>05</code> start linear address (entry point)</li></ul></li><li><code>DD..DD</code> — data bytes</li><li><code>CC</code> — checksum (two&#39;s complement of sum of all bytes from <code>LL</code>)</li></ul><p><strong>Convert:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ arm-none-eabi-objcopy -I ihex -O binary firmware.hex firmware.bin</span></span></code></pre></div><p>R2 reads <code>.hex</code> natively.</p><h2 id="motorola-s-record-s19-srec-s37-mot" tabindex="-1">Motorola S-Record (.s19, .srec, .s37, .mot) <a class="header-anchor" href="#motorola-s-record-s19-srec-s37-mot" aria-label="Permalink to &quot;Motorola S-Record (.s19, .srec, .s37, .mot)&quot;">​</a></h2><p><strong>ASCII format</strong>, line-based. Each line starts with <code>S</code>.</p><p><strong>Line format:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>SN &lt;count&gt; &lt;address (2/3/4 bytes)&gt; &lt;data&gt; &lt;checksum&gt;</span></span></code></pre></div><ul><li><code>S0</code> — header (filename)</li><li><code>S1</code>/<code>S2</code>/<code>S3</code> — data with 16/24/32-bit address</li><li><code>S5</code>/<code>S6</code> — count</li><li><code>S7</code>/<code>S8</code>/<code>S9</code> — entry point</li><li>checksum is one&#39;s complement of LSB sum</li></ul><p><strong>Convert:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ arm-none-eabi-objcopy -I srec -O binary firmware.s19 firmware.bin</span></span></code></pre></div><h2 id="uf2-usb-flashing-format" tabindex="-1">UF2 (USB Flashing Format) <a class="header-anchor" href="#uf2-usb-flashing-format" aria-label="Permalink to &quot;UF2 (USB Flashing Format)&quot;">​</a></h2><p><strong>Magic:</strong> every 512-byte block starts with two 32-bit magic words: <code>magicStart0 = 0x0A324655</code> (on disk: <code>55 46 32 0A</code>, which is the ASCII <code>UF2</code> followed by <code>0x0A</code>) at offset 0, and <code>magicStart1 = 0x9E5D5157</code> at offset 4. Each block ends with <code>magicEnd = 0x0AB16F30</code> at offset <code>0x1FC</code>.</p><p><strong>Block layout</strong> (512 bytes):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>0x00: 0x0A324655          magic1 (&quot;UF2\\n&quot;)</span></span>
<span class="line"><span>0x04: 0x9E5D5157          magic2 (start)</span></span>
<span class="line"><span>0x08: flags</span></span>
<span class="line"><span>0x0C: target address</span></span>
<span class="line"><span>0x10: payload size (typically 256)</span></span>
<span class="line"><span>0x14: block number</span></span>
<span class="line"><span>0x18: total blocks</span></span>
<span class="line"><span>0x1C: family ID (defines target chip)</span></span>
<span class="line"><span>0x20: payload (256 bytes)</span></span>
<span class="line"><span>0x1FC: 0x0AB16F30         magic3 (end)</span></span></code></pre></div><p><strong>Family IDs:</strong> RP2040 = <code>0xe48bff56</code>, SAMD21 = <code>0x68ed2b88</code>, nRF52840 = <code>0x1b57745f</code>, etc.</p><p><strong>Convert:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ uf2conv -c -o firmware.bin firmware.uf2</span></span></code></pre></div><p>Or <code>uf2utils.py</code> (Python).</p><h2 id="esp-image-format-espressif" tabindex="-1">ESP image format (Espressif) <a class="header-anchor" href="#esp-image-format-espressif" aria-label="Permalink to &quot;ESP image format (Espressif)&quot;">​</a></h2><p><strong>Magic:</strong> byte <code>0xE9</code> at offset 0.</p><p><strong>Layout:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>0x00: 0xE9                magic</span></span>
<span class="line"><span>0x01: number of segments</span></span>
<span class="line"><span>0x02: SPI flash mode (QIO, QOUT, DIO, DOUT)</span></span>
<span class="line"><span>0x03: SPI flash size + freq encoded</span></span>
<span class="line"><span>0x04: 4-byte entry point (little-endian)</span></span>
<span class="line"><span>0x08: extended header (ESP32+)</span></span>
<span class="line"><span>0x18: segment headers + payloads</span></span>
<span class="line"><span>last 32 bytes: SHA-256 of image (ESP32+, when hash_appended=1)</span></span></code></pre></div><p>Each segment header (8 bytes): load address (4) + length (4), followed by raw bytes.</p><p><strong>Inspect:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ esptool.py --chip esp32 image_info firmware.bin</span></span></code></pre></div><p><strong>Extract segments:</strong> see Chapter 14&#39;s <code>split_esp_image.py</code>.</p><h2 id="u-boot-uimage" tabindex="-1">U-Boot uImage <a class="header-anchor" href="#u-boot-uimage" aria-label="Permalink to &quot;U-Boot uImage&quot;">​</a></h2><p><strong>Magic:</strong> <code>27 05 19 56</code> (&quot;<code>&#39;\\x05\\x19V</code>&quot;) at offset 0.</p><p><strong>Header (64 bytes):</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>0x00: 0x27051956          magic</span></span>
<span class="line"><span>0x04: header CRC32</span></span>
<span class="line"><span>0x08: timestamp (big-endian)</span></span>
<span class="line"><span>0x0C: data size</span></span>
<span class="line"><span>0x10: load address</span></span>
<span class="line"><span>0x14: entry point</span></span>
<span class="line"><span>0x18: data CRC32</span></span>
<span class="line"><span>0x1C: OS (Linux=5, RTEMS=4, ...)</span></span>
<span class="line"><span>0x1D: arch (ARM=2, MIPS=5, x86=3, ...)</span></span>
<span class="line"><span>0x1E: image type (kernel=2, ramdisk=3, ...)</span></span>
<span class="line"><span>0x1F: compression (none=0, gzip=1, bzip2=2, lzma=3, ...)</span></span>
<span class="line"><span>0x20: image name (32 bytes, null-padded)</span></span>
<span class="line"><span>0x40: payload</span></span></code></pre></div><p><strong>Inspect:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ dumpimage -l firmware.uImage</span></span>
<span class="line"><span>$ dumpimage -p 0 -o kernel.gz firmware.uImage</span></span></code></pre></div><h2 id="fit-flattened-image-tree" tabindex="-1">FIT (Flattened Image Tree) <a class="header-anchor" href="#fit-flattened-image-tree" aria-label="Permalink to &quot;FIT (Flattened Image Tree)&quot;">​</a></h2><p>U-Boot&#39;s modern format. A device-tree-encoded structure containing kernel(s), DTB(s), initramfs, and configurations.</p><p><strong>Recognise:</strong> binwalk reports &quot;Flattened device tree&quot;. <code>dumpimage -l</code> expands it.</p><p><strong>Inspect:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ dumpimage -l firmware.itb</span></span>
<span class="line"><span>$ dumpimage -p 0 -o kernel.bin firmware.itb</span></span></code></pre></div><h2 id="flattened-device-tree-dtb-dtb" tabindex="-1">Flattened Device Tree (DTB / .dtb) <a class="header-anchor" href="#flattened-device-tree-dtb-dtb" aria-label="Permalink to &quot;Flattened Device Tree (DTB / .dtb)&quot;">​</a></h2><p><strong>Magic:</strong> <code>D0 0D FE ED</code> at offset 0.</p><p><strong>Header (40 bytes):</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>0x00: 0xd00dfeed          magic</span></span>
<span class="line"><span>0x04: total size</span></span>
<span class="line"><span>0x08: offset to dt_struct</span></span>
<span class="line"><span>0x0C: offset to dt_strings</span></span>
<span class="line"><span>0x10: offset to mem_rsvmap</span></span>
<span class="line"><span>0x14: version</span></span>
<span class="line"><span>0x18: last compatible version</span></span>
<span class="line"><span>0x1C: boot CPU id</span></span>
<span class="line"><span>0x20: dt_strings size</span></span>
<span class="line"><span>0x24: dt_struct size</span></span></code></pre></div><p><strong>Convert to/from text:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ dtc -I dtb -O dts -o board.dts board.dtb</span></span>
<span class="line"><span>$ dtc -I dts -O dtb -o board.dtb board.dts</span></span></code></pre></div><p>See Chapter 18 for reading DTS.</p><h2 id="squashfs" tabindex="-1">SquashFS <a class="header-anchor" href="#squashfs" aria-label="Permalink to &quot;SquashFS&quot;">​</a></h2><p><strong>Magic:</strong> <code>68 73 71 73</code> at offset 0 for modern squashfs v4 (little-endian, the format in essentially every router firmware since ~2009). Legacy squashfs ≤3.x is big-endian with <code>73 71 73 68</code> and is now extremely rare.</p><p><strong>Recognise:</strong> binwalk identifies it.</p><p><strong>Extract:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ unsquashfs firmware.squashfs</span></span>
<span class="line"><span>$ sasquatch firmware.squashfs       # for vendor-modified variants</span></span></code></pre></div><h2 id="jffs2" tabindex="-1">JFFS2 <a class="header-anchor" href="#jffs2" aria-label="Permalink to &quot;JFFS2&quot;">​</a></h2><p><strong>Magic:</strong> <code>JFFS2_MAGIC_BITMASK = 0x1985</code> at the start of each node. On little-endian flashes (the common case) the bytes on disk are <code>85 19</code>; big-endian flashes show <code>19 85</code>.</p><p><strong>Extract:</strong> <code>jefferson</code> (Python tool) handles most variants.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ jefferson firmware.jffs2 -d output/</span></span></code></pre></div><h2 id="cramfs-romfs" tabindex="-1">CramFS, RomFS <a class="header-anchor" href="#cramfs-romfs" aria-label="Permalink to &quot;CramFS, RomFS&quot;">​</a></h2><p>Older read-only filesystems. Magic <code>45 3D CD 28</code> (CramFS) and <code>-rom1fs-</code> (RomFS). <code>unromfs</code>, <code>cramfsck</code> for extraction.</p><h2 id="compression-formats" tabindex="-1">Compression formats <a class="header-anchor" href="#compression-formats" aria-label="Permalink to &quot;Compression formats&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Magic</th><th>Format</th><th>Decompress with</th></tr></thead><tbody><tr><td><code>1F 8B</code></td><td>gzip</td><td><code>gunzip</code>, <code>zcat</code></td></tr><tr><td><code>42 5A 68</code></td><td>bzip2</td><td><code>bunzip2</code></td></tr><tr><td><code>5D 00 00</code></td><td>LZMA (legacy)</td><td><code>unlzma</code></td></tr><tr><td><code>FD 37 7A 58 5A 00</code></td><td>XZ</td><td><code>xz -d</code></td></tr><tr><td><code>28 B5 2F FD</code></td><td>Zstandard</td><td><code>zstd -d</code></td></tr><tr><td><code>04 22 4D 18</code></td><td>LZ4 frame</td><td><code>lz4 -d</code></td></tr><tr><td><code>89 4C 5A 4F 00 0D 0A 1A 0A</code></td><td>LZO</td><td><code>lzop -d</code></td></tr><tr><td><code>50 4B 03 04</code></td><td>ZIP</td><td><code>unzip</code></td></tr><tr><td><code>52 61 72 21 1A 07</code></td><td>RAR</td><td><code>unrar</code></td></tr><tr><td><code>Rar!</code></td><td>ditto, ASCII</td><td><code>unrar</code></td></tr></tbody></table><h2 id="cryptographic-blobs" tabindex="-1">Cryptographic blobs <a class="header-anchor" href="#cryptographic-blobs" aria-label="Permalink to &quot;Cryptographic blobs&quot;">​</a></h2><p><strong>X.509 certificate:</strong> for the common size range (256 B – 64 KiB), the DER-encoded cert starts with <code>30 82</code> (SEQUENCE with 2-byte length). Smaller certs are <code>30 81 LL</code>, larger are <code>30 83 LL LL LL</code>. Often inside <code>-----BEGIN CERTIFICATE-----</code> PEM headers when in text form.</p><p><strong>RSA public key (PKCS#1 DER):</strong> starts with <code>30 82</code> for the SEQUENCE, then INTEGER (modulus) and INTEGER (exponent).</p><p><strong>Ed25519 public key:</strong> 32 bytes, indistinguishable from random. Tell by context (a 32-byte block in <code>.rodata</code> near a signature-verification function).</p><p><strong>ECDSA signature:</strong> typically 70–72 bytes DER-encoded.</p><p><strong>AES key:</strong> 16/24/32 bytes, indistinguishable from random.</p><h2 id="vendor-specific-firmware-containers" tabindex="-1">Vendor-specific firmware containers <a class="header-anchor" href="#vendor-specific-firmware-containers" aria-label="Permalink to &quot;Vendor-specific firmware containers&quot;">​</a></h2><p>These vary widely. binwalk recognises many:</p><ul><li><strong>Realtek RTKBoot:</strong> &quot;RTKBoot&quot; header.</li><li><strong>Allwinner eGON:</strong> &quot;eGON.BT0&quot; magic.</li><li><strong>Rockchip RKFW:</strong> &quot;RKFW&quot; header.</li><li><strong>MediaTek BootROM image:</strong> specific 32-byte preamble.</li><li><strong>Broadcom CFE bootloader:</strong> custom CFE header.</li><li><strong>TP-Link Atheros header:</strong> offset 0x100, custom structure.</li></ul><p>For each, the recipe is the same: <code>binwalk</code> finds the boundary, <code>dd</code> strips, the rest is a normal image you can load in r2.</p><h2 id="quick-triage-workflow" tabindex="-1">Quick triage workflow <a class="header-anchor" href="#quick-triage-workflow" aria-label="Permalink to &quot;Quick triage workflow&quot;">​</a></h2><p>For an unknown blob, in order:</p><ol><li><code>xxd file | head -2</code> — first bytes for instant recognition.</li><li><code>file file</code> — libmagic guess.</li><li><code>binwalk file</code> — embedded format scan.</li><li><code>binwalk -E file</code> — entropy plot.</li><li><code>cpu_rec.py file</code> — architecture guess if nothing else.</li><li><code>strings -n 8 file | head -50</code> — human-readable hints.</li><li><code>binwalk -e file</code> — extract everything binwalk recognises.</li></ol><p>This sequence, run on every new binary, will identify 95% of what you encounter in the field.</p>`,85)])])}const m=a(o,[["render",i]]);export{g as __pageData,m as default};
